#!/usr/bin/env node
// Generates the theme stylesheet and the Rust token constants from
// src/styles/tokens.json, the single source of the design tokens.
//
//   node scripts/tokens/generate.mjs          rewrite the generated files
//   node scripts/tokens/generate.mjs --check  fail when they are out of date
//
// The stylesheet is emitted byte for byte as it was handwritten before this
// script existed: tokens.json was extracted from it, so a regenerated file
// that differs from the committed one means a token changed, not that the
// formatting drifted. Nothing here invents a value; every number comes from
// the JSON.
//
// Radius lives in the default theme's block, next to the other variables the
// stylesheet serves from `:root`, and in the `@theme` block that maps the
// Tailwind colour utilities to those variables.
//
// The two groups below are presentation, not data: they say where a variable
// belongs in the stylesheet, which no token value can express. A colour that
// is in tokens.json but in neither group fails the run instead of vanishing.

import { readFileSync, writeFileSync } from "node:fs"
import { dirname, join, relative } from "node:path"
import { fileURLToPath } from "node:url"

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..")
const TOKENS = join(ROOT, "src", "styles", "tokens.json")
const CSS = join(ROOT, "src", "styles", "themes.css")
const PALETTE = join(ROOT, "crates", "tterm-ui", "src", "tokens", "palette.rs")
const TYPE_SCALE = join(ROOT, "crates", "tterm-ui", "src", "tokens", "type_scale.rs")

// The order Tailwind's colour utilities are declared in.
const TAILWIND_COLORS = [
  "border",
  "input",
  "ring",
  "background",
  "foreground",
  "primary",
  "primary-foreground",
  "secondary",
  "secondary-foreground",
  "muted",
  "muted-foreground",
  "accent",
  "accent-foreground",
  "destructive",
  "destructive-foreground",
  "card",
  "card-foreground",
  "popover",
  "popover-foreground",
  "success",
  "success-foreground",
  "warning",
  "warning-foreground",
]

// The order the variables are declared in inside a theme, grouped the way the
// blank lines group them.
const GROUPS = [
  ["background", ["background", "foreground"]],
  ["card", ["card", "card-foreground"]],
  ["popover", ["popover", "popover-foreground"]],
  ["primary", ["primary", "primary-foreground"]],
  ["secondary", ["secondary", "secondary-foreground"]],
  ["muted", ["muted", "muted-foreground"]],
  ["accent", ["accent", "accent-foreground"]],
  [
    "status",
    [
      "destructive",
      "destructive-foreground",
      "success",
      "success-foreground",
      "warning",
      "warning-foreground",
    ],
  ],
  ["border", ["border", "input", "ring"]],
  ["tabs", ["tab-background", "tab-active", "tab-active-border", "tab-hover", "titlebar"]],
]

const THEME_COLORS = GROUPS.flatMap(([, names]) => names)

function fail(message) {
  console.error(`tokens: ${message}`)
  process.exit(1)
}

const stylesheet = (tokens) => {
  const themeBlocks = tokens.themes.map((theme) => {
    const lines = [`  ${theme.selector} {`]
    for (const [group, names] of GROUPS) {
      if (group === "tabs" && theme.selector === ":root") {
        lines.push(`    --radius: ${tokens.radiusRem}rem;`, "")
      }
      const comment = theme.comments?.[group]
      if (comment !== undefined) lines.push(...commentLines(comment))
      lines.push(...names.map((name) => `    --${name}: ${theme.colors[name]};`), "")
    }
    lines.pop()
    lines.push("  }")
    return lines.join("\n")
  })

  return `@layer overrides;
@import "tailwindcss";

@custom-variant dark (&:where(:not([data-theme="light"], [data-theme="light"] *)));

@theme {
${TAILWIND_COLORS.map((name) => `  --color-${name}: hsl(var(--${name}));`).join("\n")}

  --radius: ${tokens.radiusRem}rem;
}

@layer base {
${themeBlocks.join("\n\n")}
}

@layer base {
  * {
    border-color: hsl(var(--border));
  }
  body {
    background-color: hsl(var(--background));
    color: hsl(var(--foreground));
    font-feature-settings:
      "rlig" 1,
      "calt" 1;
  }
}
`
}

// The continuation lines of a multi-line CSS comment line up under the text of
// the first one, which is what the handwritten stylesheet did.
const commentLines = (text) => {
  const [first, ...rest] = text.split("\n")
  if (rest.length === 0) return [`    /* ${first} */`]
  const continuation = rest.map((line) => `       ${line}`)
  continuation[continuation.length - 1] += " */"
  return [`    /* ${first}`, ...continuation]
}

const rust = (tokens) => {
  const header = `// Generated by scripts/tokens/generate.mjs from src/styles/tokens.json.
// Do not edit: change tokens.json and run \`pnpm tokens:generate\`.
`
  const colors = tokens.themes.map((theme) => {
    const fields = THEME_COLORS.map(
      (name) => `        ${field(name)}: ${hsl(theme.colors[name])},`
    )
    return `/// The ${theme.selector === ":root" ? `${theme.name} theme, which \`${theme.selector}\` serves as the default.` : `${theme.name} theme.`}
pub const ${constant(theme.name)}: Theme = Theme {
    id: "${theme.name}",
    colors: Colors {
${fields.join("\n")}
    },
};`
  })

  const palette = `${header}
use crate::tokens::color::Hsl;
use crate::tokens::theme::Theme;

/// The corner radius every theme shares, as \`--radius\` states it in rem.
pub const RADIUS_REM: f32 = ${tokens.radiusRem};

/// The colours of one theme, by the CSS variable name without its \`--\`.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Colors {
${THEME_COLORS.map((name) => `    pub ${field(name)}: Hsl,`).join("\n")}
}

impl Colors {
    /// The colour declared for \`name\`, or \`None\` when the theme has no such
    /// variable. Porting a stylesheet rule can look a colour up by the name it
    /// uses instead of repeating the value.
    pub fn get(&self, name: &str) -> Option<Hsl> {
        Some(match name {
${THEME_COLORS.map((name) => `            "${name}" => self.${field(name)},`).join("\n")}
            _ => return None,
        })
    }
}

${colors.join("\n\n")}

/// Every theme the stylesheet defines, in the order it defines them.
pub const THEMES: [Theme; ${tokens.themes.length}] = [${tokens.themes
    .map((theme) => constant(theme.name))
    .join(", ")}];
`

  const typeScale = `${header}
use crate::tokens::font_size::FontSize;

${Object.entries(tokens.fontSizes)
  .map(
    ([name, size]) => `/// \`--text-${name}\` at 100% interface scale.
pub const ${constant(`text-${name}`)}: FontSize = ${fontSize(size)};`
  )
  .join("\n\n")}

/// Every interface font size, keyed by the suffix of its \`--text-<name>\`
/// variable, in the order the stylesheet applies them.
pub const FONT_SIZES: [(&str, FontSize); ${Object.keys(tokens.fontSizes).length}] = [
${Object.entries(tokens.fontSizes)
  .map(([name]) => `    ("${name}", ${constant(`text-${name}`)}),`)
  .join("\n")}
];
`

  return { palette, typeScale }
}

// `card-foreground` exports as `CARD_FOREGROUND` and names the field
// `card_foreground`.
const constant = (name) => name.replaceAll("-", "_").toUpperCase()
const field = (name) => name.replaceAll("-", "_")
// rustfmt expands a two-field struct literal on its own line, so the
// generator writes it that way and `cargo fmt --check` stays green.
const fontSize = ({ rem, lineHeight }) => `FontSize {
    rem: ${float(rem)},
    line_height: ${float(lineHeight)},
}`

// `233 12% 34%` is the CSS `hsl()` syntax without the function, which is how
// the stylesheet states every colour.
const hsl = (value) => {
  const match = value.match(/^([\d.]+) ([\d.]+)% ([\d.]+)%$/)
  if (!match) fail(`"${value}" is not an "<hue> <saturation>% <lightness>%" colour`)
  const [, hue, saturation, lightness] = match
  return `Hsl::new(${float(hue)}, ${float(saturation)}, ${float(lightness)})`
}

// Rust infers a literal without a decimal point as an integer, which a field
// of type `f32` rejects, so a whole number keeps its `.0`.
const float = (value) => {
  const number = Number(value)
  return Number.isInteger(number) ? number.toFixed(1) : String(number)
}

const validate = (tokens) => {
  const names = new Set(tokens.themes.map((theme) => theme.name))
  if (names.size !== tokens.themes.length) fail("two themes share a name")
  if (tokens.themes.filter((theme) => theme.selector === ":root").length !== 1) {
    fail("exactly one theme must be served from :root")
  }
  if (THEME_COLORS.length !== new Set(THEME_COLORS).size) fail("a colour is in two groups")

  for (const theme of tokens.themes) {
    for (const group of Object.keys(theme.comments ?? {})) {
      if (!GROUPS.some(([name]) => name === group)) {
        fail(`${theme.name} comments on ${group}, which no group names`)
      }
    }
    const declared = Object.keys(theme.colors)
    const unknown = declared.filter((name) => !THEME_COLORS.includes(name))
    const missing = THEME_COLORS.filter((name) => !(name in theme.colors))
    if (unknown.length > 0) fail(`${theme.name} declares ${unknown.join(", ")}, which no group places`)
    if (missing.length > 0) fail(`${theme.name} is missing ${missing.join(", ")}`)
  }

  for (const name of TAILWIND_COLORS) {
    if (!THEME_COLORS.includes(name)) fail(`the @theme block maps ${name}, which no theme declares`)
  }
}

const tokens = JSON.parse(readFileSync(TOKENS, "utf8"))
validate(tokens)

const { palette, typeScale } = rust(tokens)
const outputs = [
  [CSS, stylesheet(tokens)],
  [PALETTE, palette],
  [TYPE_SCALE, typeScale],
]

if (process.argv.includes("--check")) {
  const stale = outputs.filter(([path, text]) => {
    try {
      return readFileSync(path, "utf8") !== text
    } catch {
      return true
    }
  })
  if (stale.length > 0) {
    fail(
      `${stale.map(([path]) => relative(ROOT, path)).join(", ")} no longer match tokens.json; ` +
        "run `pnpm tokens:generate`"
    )
  }
} else {
  for (const [path, text] of outputs) writeFileSync(path, text)
}
